        a10[11] = "Solaris 10 x86 (ZFS Root Storage)|\u041f\u0440\u043e\u043c\u044b\u0448\u043b\u0435\u043d\u043d\u0430\u044f Unix-\u0441\u0438\u0441\u0442\u0435\u043c\u0430 \u043e\u0442 Sun Microsystems \u043d\u0430 \u0431\u044b\u0442\u043e\u0432\u043e\u043c \u0436\u0435\u043b\u0435\u0437\u0435";
