        String[] a11 = new String[12];
        a11[0] = "Cyberpunk 2077: Phantom Liberty|\u0423\u0440\u0435\u0437\u0430\u043d\u0438\u0435 \u0440\u0430\u0437\u0440\u0435\u0448\u0435\u043d\u0438\u044f \u0434\u043e 320x240, FSR 3 Ultra Performance, Potato Mod";
        a11[1] = "Crysis (2007) Very High DirectX 10|\u0417\u0430\u043f\u0443\u0441\u043a \u0431\u0435\u043d\u0447\u043c\u0430\u0440\u043a\u0430 Crysis 'Can It Run Crysis?' \u043d\u0430 \u043f\u0440\u0435\u0434\u0435\u043b\u044c\u043d\u044b\u0445 \u043d\u0430\u0441\u0442\u0440\u043e\u0439\u043a\u0430\u0445";
        a11[2] = "Grand Theft Auto V (DirectX 11)|Low-spec \u043a\u043e\u043d\u0444\u0438\u0433, \u0443\u0434\u0430\u043b\u0435\u043d\u0438\u0435 \u0442\u0435\u043d\u0435\u0439 \u0438 \u0442\u0440\u0430\u0444\u0438\u043a\u0430, \u0448\u0435\u0439\u0434\u0435\u0440\u043d\u044b\u0439 \u0444\u0438\u043a\u0441 \u0434\u043b\u044f \u0441\u043b\u0430\u0431\u044b\u0445 \u043a\u0430\u0440\u0442";
        a11[3] = "DOOM Eternal (Vulkan API)|\u042d\u043c\u0443\u043b\u044f\u0446\u0438\u044f \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0439 Vulkan \u0447\u0435\u0440\u0435\u0437 VKD3D \u0438 Direct3D 11 \u0442\u0440\u0430\u043d\u0441\u043b\u044f\u0442\u043e\u0440";
        a11[4] = "The Witcher 3: Wild Hunt Next-Gen|\u041f\u0430\u0442\u0447 \u043d\u0430 \u043e\u0442\u043a\u043b\u044e\u0447\u0435\u043d\u0438\u0435 \u0442\u0440\u0430\u0441\u0441\u0438\u0440\u043e\u0432\u043a\u0438 \u043b\u0443\u0447\u0435\u0439 \u0438 \u0443\u043f\u0440\u043e\u0449\u0451\u043d\u043d\u0443\u044e \u0433\u0435\u043e\u043c\u0435\u0442\u0440\u0438\u044e \u043b\u0438\u0441\u0442\u0432\u044b";
        a11[5] = "Starfield (Creation Engine 2)|\u0423\u0434\u0430\u043b\u0435\u043d\u0438\u0435 \u043e\u0431\u044a\u0435\u043c\u043d\u043e\u0433\u043e \u0442\u0443\u043c\u0430\u043d\u0430 \u0438 \u0437\u0430\u043c\u0435\u043d\u0430 \u0442\u0435\u043a\u0441\u0442\u0443\u0440 \u043f\u043b\u0430\u043d\u0435\u0442 \u043d\u0430 128x128 \u043f\u0438\u043a\u0441\u0435\u043b\u0435\u0439";
        a11[6] = "Black Myth: Wukong (Unreal Engine 5)|Nanite \u0438 Lumen \u043e\u0442\u043a\u043b\u044e\u0447\u0435\u043d\u044b, \u0440\u0430\u0437\u0440\u0435\u0448\u0435\u043d\u0438\u0435 \u0440\u0435\u043d\u0434\u0435\u0440\u0430 25%, \u044d\u043c\u0443\u043b\u044f\u0446\u0438\u044f DX12";
        a11[7] = "Half-Life 2 (DirectX 7 Fallback)|\u041f\u0440\u0438\u043d\u0443\u0434\u0438\u0442\u0435\u043b\u044c\u043d\u044b\u0439 \u0437\u0430\u043f\u0443\u0441\u043a Source Engine \u0432 \u0440\u0435\u0436\u0438\u043c\u0435 mat_dxlevel 70 \u0431\u0435\u0437 \u043f\u0438\u043a\u0441\u0435\u043b\u044c\u043d\u044b\u0445 \u0448\u0435\u0439\u0434\u0435\u0440\u043e\u0432";
        a11[8] = "Quake III Arena (1000 FPS Challenge)|\u0412\u044b\u0436\u0438\u043c\u0430\u043d\u0438\u0435 \u043c\u0430\u043a\u0441\u0438\u043c\u0430\u043b\u044c\u043d\u043e\u0433\u043e \u0444\u0440\u0435\u0439\u043c\u0440\u0435\u0439\u0442\u0430 \u0432 timerefresh demo four.dm_68";
        a11[9] = "Minecraft Java Edition + SEUS PTGI Shaders|\u0417\u0430\u043f\u0443\u0441\u043a \u0442\u0440\u0430\u0441\u0441\u0438\u0440\u043e\u0432\u043a\u0438 \u043b\u0443\u0447\u0435\u0439 \u0448\u0435\u0439\u0434\u0435\u0440\u043e\u0432 OptiFine \u043d\u0430 \u043d\u0435\u043f\u043e\u0434\u0434\u0435\u0440\u0436\u0438\u0432\u0430\u0435\u043c\u043e\u043c \u0432\u0438\u0434\u0435\u043e\u0447\u0438\u043f\u0435";
        a11[10] = "Alan Wake 2 (Mesh Shaders Bypass)|\u041e\u0431\u0445\u043e\u0434 \u043e\u0431\u044f\u0437\u0430\u0442\u0435\u043b\u044c\u043d\u043e\u0433\u043e \u0442\u0440\u0435\u0431\u043e\u0432\u0430\u043d\u0438\u044f Mesh Shaders \u0447\u0435\u0440\u0435\u0437 \u044d\u043c\u0443\u043b\u044f\u0442\u043e\u0440 vkd3d-proton";
        a11[11] = "S.T.A.L.K.E.R. 2: Heart of Chornobyl|\u0417\u0430\u043f\u0443\u0441\u043a \u0437\u043e\u043d\u044b \u043e\u0442\u0447\u0443\u0436\u0434\u0435\u043d\u0438\u044f \u043d\u0430 \u0441\u0432\u0435\u0440\u0445\u043d\u0438\u0437\u043a\u0438\u0445 \u043d\u0430\u0441\u0442\u0440\u043e\u0439\u043a\u0430\u0445 \u043f\u0430\u043c\u044f\u0442\u0438";
        a9[1] = a11;
        String[] a12 = new String[10];
        a12[0] = "\u0416\u0438\u0434\u043a\u0438\u0439 \u0430\u0437\u043e\u0442 LN2 (-196\u00b0C) \u0438 \u0412\u043e\u043b\u044c\u0442\u043c\u043e\u0434 VCore|\u0423\u0441\u0442\u0430\u043d\u043e\u0432\u043a\u0430 \u043c\u0435\u0434\u043d\u043e\u0433\u043e \u0441\u0442\u0430\u043a\u0430\u043d\u0430 \u043f\u043e\u0434 LN2, \u043f\u043e\u0434\u043d\u044f\u0442\u0438\u0435 VCore \u043d\u0430 +40%, \u043f\u043e\u0438\u0441\u043a \u0432\u0430\u043b\u0438\u0434\u0430\u0446\u0438\u0438 CPU-Z";
        a12[1] = "\u041f\u0440\u0435\u0434\u0435\u043b \u0448\u0438\u043d\u044b BCLK / FSB \u0438 \u0434\u0435\u043b\u0438\u0442\u0435\u043b\u0435\u0439 RAM|\u0424\u043e\u0440\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u0435 \u0448\u0438\u043d\u044b \u0434\u043e \u0443\u043f\u043e\u0440\u0430 \u043c\u0430\u0442\u0435\u0440\u0438\u043d\u0441\u043a\u043e\u0439 \u043f\u043b\u0430\u0442\u044b, \u043e\u043f\u0442\u0438\u043c\u0438\u0437\u0430\u0446\u0438\u044f \u0441\u0443\u0431\u0442\u0430\u0439\u043c\u0438\u043d\u0433\u043e\u0432 \u043f\u0430\u043c\u044f\u0442\u0438";
        a12[2] = "\u0421\u043a\u0430\u043b\u044c\u043f\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u0435 (Delid) \u0438 \u0416\u0438\u0434\u043a\u0438\u0439 \u041c\u0435\u0442\u0430\u043b\u043b|\u0421\u043d\u044f\u0442\u0438\u0435 \u0442\u0435\u043f\u043b\u043e\u0440\u0430\u0441\u043f\u0440\u0435\u0434\u0435\u043b\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0439 \u043a\u0440\u044b\u0448\u043a\u0438 IHS, \u043d\u0430\u043d\u0435\u0441\u0435\u043d\u0438\u0435 Gallium Liquid Pro";
        a12[3] = "FurMark GPU Donut '\u041f\u0435\u0447\u044c' & Prime95 Small FFT|\u041e\u0434\u043d\u043e\u0432\u0440\u0435\u043c\u0435\u043d\u043d\u044b\u0439 \u0441\u0442\u0440\u0435\u0441\u0441-\u0442\u0435\u0441\u0442 VRM \u0444\u0430\u0437 \u043f\u0438\u0442\u0430\u043d\u0438\u044f \u0434\u043e \u0442\u0435\u043c\u043f\u0435\u0440\u0430\u0442\u0443\u0440\u044b \u043f\u043b\u0430\u0432\u043b\u0435\u043d\u0438\u044f \u043f\u0440\u0438\u043f\u043e\u044f";
        a12[4] = "Peltier TEC \u042d\u043b\u0435\u043c\u0435\u043d\u0442 + \u0427\u0438\u043b\u043b\u0435\u0440\u043d\u0430\u044f \u0432\u043e\u0434\u0430|\u0422\u0435\u0440\u043c\u043e\u044d\u043b\u0435\u043a\u0442\u0440\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u043c\u043e\u0434\u0443\u043b\u044c \u041f\u0435\u043b\u044c\u0442\u044c\u0435 250W \u043f\u0440\u043e\u0442\u0438\u0432 \u0442\u043e\u0447\u043a\u0438 \u0440\u043e\u0441\u044b \u0438 \u043a\u043e\u043d\u0434\u0435\u043d\u0441\u0430\u0442\u0430";
        a12[5] = "\u041a\u0430\u0440\u0430\u043d\u0434\u0430\u0448\u043d\u044b\u0439 \u0432\u043e\u043b\u044c\u0442\u043c\u043e\u0434 (Pencil Mod) \u0440\u0435\u0437\u0438\u0441\u0442\u043e\u0440\u043e\u0432|\u0417\u0430\u043a\u0440\u0430\u0448\u0438\u0432\u0430\u043d\u0438\u0435 SMD-\u0440\u0435\u0437\u0438\u0441\u0442\u043e\u0440\u043e\u0432 \u0433\u0440\u0438\u0444\u0435\u043b\u0435\u043c \u0434\u043b\u044f \u0441\u043d\u0438\u0436\u0435\u043d\u0438\u044f VDrop \u043f\u043e\u0434 \u043d\u0430\u0433\u0440\u0443\u0437\u043a\u043e\u0439";
        a12[6] = "\u0421\u0438\u043d\u0445\u0440\u043e\u043d\u043d\u044b\u0439 \u0440\u0430\u0437\u0433\u043e\u043d VRAM GDDR \u0434\u043e \u0430\u0440\u0442\u0435\u0444\u0430\u043a\u0442\u043e\u0432|\u0423\u0436\u0435\u0441\u0442\u043e\u0447\u0435\u043d\u0438\u0435 \u0442\u0430\u0439\u043c\u0438\u043d\u0433\u043e\u0432 \u0432\u0438\u0434\u0435\u043e\u043f\u0430\u043c\u044f\u0442\u0438 \u0438 \u043f\u043e\u0438\u0441\u043a \u043c\u0430\u043a\u0441\u0438\u043c\u0430\u043b\u044c\u043d\u043e\u0439 \u0447\u0430\u0441\u0442\u043e\u0442\u044b \u0431\u0435\u0437 \u0448\u0430\u0445\u043c\u0430\u0442\u043d\u044b\u0445 \u0441\u0435\u0442\u043e\u043a";
        a12[7] = "\u0420\u0430\u0437\u0433\u043e\u043d \u0448\u0438\u043d\u044b AGP / PCI \u0434\u043e 100MHz|\u041f\u043e\u0432\u044b\u0448\u0435\u043d\u0438\u0435 \u0447\u0430\u0441\u0442\u043e\u0442\u044b \u0441\u0438\u0441\u0442\u0435\u043c\u043d\u044b\u0445 \u0441\u043b\u043e\u0442\u043e\u0432 AGP (66->100MHz) \u0434\u043b\u044f \u0443\u0434\u0432\u043e\u0435\u043d\u0438\u044f \u043f\u0440\u043e\u043f\u0443\u0441\u043a\u043d\u043e\u0439 \u0441\u043f\u043e\u0441\u043e\u0431\u043d\u043e\u0441\u0442\u0438";
        a12[8] = "\u0421\u0443\u0438\u0446\u0438\u0434\u0430\u043b\u044c\u043d\u044b\u0439 \u0441\u043a\u0440\u0438\u043d\u0448\u043e\u0442\u043d\u044b\u0439 \u0440\u0430\u0437\u0433\u043e\u043d 5+ GHz|\u042d\u043a\u0441\u0442\u0440\u0435\u043c\u0430\u043b\u044c\u043d\u044b\u0439 \u0440\u044b\u0432\u043e\u043a \u043f\u043e \u043c\u043d\u043e\u0436\u0438\u0442\u0435\u043b\u044e \u0440\u0430\u0434\u0438 \u043e\u0434\u043d\u043e\u0433\u043e \u043a\u0430\u0434\u0440\u0430 CPU-Z \u0434\u043e \u0442\u0435\u043f\u043b\u043e\u0432\u043e\u0433\u043e \u043f\u0440\u043e\u0431\u043e\u044f";
        a12[9] = "\u0422\u0435\u0441\u0442 Linpack 10000 MFlops \u043d\u0430 \u043e\u0442\u043a\u0430\u0437|\u0414\u043b\u0438\u0442\u0435\u043b\u044c\u043d\u044b\u0439 \u043c\u0430\u0442\u0435\u043c\u0430\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u043f\u0440\u043e\u0433\u043e\u043d \u0441 \u043c\u0430\u043a\u0441\u0438\u043c\u0430\u043b\u044c\u043d\u044b\u043c \u0437\u0430\u0434\u0435\u0439\u0441\u0442\u0432\u043e\u0432\u0430\u043d\u0438\u0435\u043c \u043a\u044d\u0448-\u043f\u0430\u043c\u044f\u0442\u0438";
        a9[2] = a12;
        String[] a13 = new String[8];
        a13[0] = "3D Raycaster \u0434\u0432\u0438\u0436\u043e\u043a \u043d\u0430 \u0447\u0438\u0441\u0442\u043e\u043c x86 ASM|\u041d\u0430\u043f\u0438\u0441\u0430\u043d\u0438\u0435 \u043f\u0441\u0435\u0432\u0434\u043e-3D \u0434\u0432\u0438\u0436\u043a\u0430 \u0442\u0438\u043f\u0430 Wolfenstein 3D \u0441 \u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u043e\u0439 \u0442\u043e\u0447\u043a\u043e\u0439 (Fixed-Point math)";
        a13[1] = "4KB \u0414\u0435\u043c\u043e\u0441\u0446\u0435\u043d\u0430 \u0441 \u043f\u0440\u043e\u0446\u0435\u0434\u0443\u0440\u043d\u043e\u0439 \u043c\u0443\u0437\u044b\u043a\u043e\u0439 \u0438 \u0444\u0440\u0430\u043a\u0442\u0430\u043b\u0430\u043c\u0438|\u0423\u043f\u0430\u043a\u043e\u0432\u043a\u0430 3D-\u0433\u0440\u0430\u0444\u0438\u043a\u0438, \u043f\u043b\u0430\u0437\u043c\u044b \u0438 \u0442\u0440\u0435\u043a\u0435\u0440\u043d\u043e\u0433\u043e \u0441\u0438\u043d\u0442\u0435\u0437\u0430\u0442\u043e\u0440\u0430 \u0432 \u0438\u0441\u043f\u043e\u043b\u043d\u044f\u0435\u043c\u044b\u0439 COM-\u0444\u0430\u0439\u043b 4096 \u0431\u0430\u0439\u0442";
        a13[2] = "\u0421\u0432\u043e\u044f \u041e\u0421 \u0440\u0435\u0430\u043b\u044c\u043d\u043e\u0433\u043e \u0432\u0440\u0435\u043c\u0435\u043d\u0438 \u043d\u0430 C \u0438 \u0410\u0441\u0441\u0435\u043c\u0431\u043b\u0435\u0440\u0435|\u041d\u0430\u043f\u0438\u0441\u0430\u043d\u0438\u0435 MBR \u0437\u0430\u0433\u0440\u0443\u0437\u0447\u0438\u043a\u0430, \u043f\u0435\u0440\u0435\u0445\u043e\u0434 \u0432 \u0437\u0430\u0449\u0438\u0449\u0435\u043d\u043d\u044b\u0439 32-\u0431\u0438\u0442 \u0440\u0435\u0436\u0438\u043c, \u0434\u0440\u0430\u0439\u0432\u0435\u0440 VGA \u0438 \u043a\u043b\u0430\u0432\u0438\u0430\u0442\u0443\u0440\u044b";
        a13[3] = "\u041d\u0435\u0439\u0440\u043e\u0441\u0435\u0442\u044c \u0440\u0430\u0441\u043f\u043e\u0437\u043d\u0430\u0432\u0430\u043d\u0438\u044f \u0446\u0438\u0444\u0440 \u043d\u0430 3dfx Glide API|\u0418\u0441\u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u043d\u0438\u0435 \u0442\u0435\u043a\u0441\u0442\u0443\u0440\u043d\u044b\u0445 \u0431\u043b\u043e\u043a\u043e\u0432 TMU 3Dfx Voodoo \u0434\u043b\u044f \u0442\u0435\u043d\u0437\u043e\u0440\u043d\u044b\u0445 \u043c\u0430\u0442\u0440\u0438\u0447\u043d\u044b\u0445 \u0443\u043c\u043d\u043e\u0436\u0435\u043d\u0438\u0439";
        a13[4] = "\u041a\u0430\u0441\u0442\u043e\u043c\u043d\u044b\u0439 \u043a\u0440\u0438\u043f\u0442\u043e-\u043c\u0430\u0439\u043d\u0435\u0440 \u0434\u043b\u044f \u043a\u043b\u0430\u0441\u0442\u0435\u0440\u0430 \u0441\u043b\u0430\u0431\u044b\u0445 CPU|\u041e\u043f\u0442\u0438\u043c\u0438\u0437\u0430\u0446\u0438\u044f \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0439 SIMD / MMX / SSE \u0434\u043b\u044f \u0432\u044b\u0447\u0438\u0441\u043b\u0435\u043d\u0438\u044f \u0445\u044d\u0448\u0435\u0439 RandomX";
        a13[5] = "Voxel 3D \u043b\u0430\u043d\u0434\u0448\u0430\u0444\u0442\u043d\u044b\u0439 \u0434\u0432\u0438\u0436\u043e\u043a \u0432 \u0441\u0442\u0438\u043b\u0435 Comanche|\u0420\u0435\u043d\u0434\u0435\u0440\u0438\u043d\u0433 \u043a\u0430\u0440\u0442 \u0432\u044b\u0441\u043e\u0442 \u043f\u043e \u0430\u043b\u0433\u043e\u0440\u0438\u0442\u043c\u0443 Raymarching \u0441 60 FPS \u0431\u0435\u0437 \u0430\u043f\u043f\u0430\u0440\u0430\u0442\u043d\u043e\u0433\u043e 3D-\u0443\u0441\u043a\u043e\u0440\u0438\u0442\u0435\u043b\u044f";
        a13[6] = "\u042d\u043c\u0443\u043b\u044f\u0442\u043e\u0440 Game Boy Color \u043d\u0430 PDA / \u041a\u041f\u041a|\u0411\u044b\u0441\u0442\u0440\u044b\u0439 JIT-\u0440\u0435\u043a\u043e\u043c\u043f\u0438\u043b\u044f\u0442\u043e\u0440 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0439 Z80 \u0432 \u043e\u043f\u043a\u043e\u0434\u044b ARM \u0441 \u043f\u0440\u044f\u043c\u043e\u0439 \u043e\u0442\u0440\u0438\u0441\u043e\u0432\u043a\u043e\u0439 \u0432 Framebuffer";
        a13[7] = "\u0421\u0438\u043d\u0442\u0435\u0437\u0430\u0442\u043e\u0440 \u0447\u0438\u043f\u0442\u044e\u043d\u0430 SID 6581 \u043d\u0430 \u0442\u0430\u0439\u043c\u0435\u0440\u0435 i8253|\u0413\u0435\u043d\u0435\u0440\u0430\u0446\u0438\u044f 3-\u0433\u043e\u043b\u043e\u0441\u043d\u043e\u0433\u043e \u043f\u043e\u043b\u0438\u0444\u043e\u043d\u0438\u0447\u0435\u0441\u043a\u043e\u0433\u043e \u0437\u0432\u0443\u043a\u0430 \u0447\u0435\u0440\u0435\u0437 \u043e\u0434\u0438\u043d 1-\u0431\u0438\u0442\u043d\u044b\u0439 \u0441\u0438\u0441\u0442\u0435\u043c\u043d\u044b\u0439 \u0434\u0438\u043d\u0430\u043c\u0438\u043a PC Speaker";
        a9[3] = a13;
        String[] a14 = new String[14];
        a14[0] = "LGA 771 \u043d\u0430 775 Xeon Mod (X5460 3.16GHz 12MB)|\u041d\u0430\u043a\u043b\u0435\u0439\u043a\u0430-\u0430\u0434\u0430\u043f\u0442\u0435\u0440 \u043a\u043e\u043d\u0442\u0430\u043a\u0442\u043e\u0432, \u0441\u043f\u0438\u043b \u043a\u043b\u044e\u0447\u0435\u0439 \u0441\u043e\u043a\u0435\u0442\u0430 LGA775 \u0438 \u043f\u0440\u043e\u0448\u0438\u0432\u043a\u0430 \u043c\u0438\u043a\u0440\u043e\u043a\u043e\u0434\u043e\u0432 Xeon";
        a14[1] = "LGA 1151v1 CoffeeTime Mod (Core i9-9900K 8C/16T)|\u0418\u0437\u043e\u043b\u044f\u0446\u0438\u044f \u043a\u043e\u043d\u0442\u0430\u043a\u0442\u043e\u0432 SKTOCC \u043a\u0430\u043f\u0442\u043e\u043d\u043e\u0432\u044b\u043c \u0441\u043a\u043e\u0442\u0447\u0435\u043c, \u043f\u0435\u0440\u0435\u043c\u044b\u0447\u043a\u0438 \u0438 \u043c\u043e\u0434 BIOS CoffeeTime \u043d\u0430 Z170";
        a14[2] = "Asus CT-479 \u0410\u0434\u0430\u043f\u0442\u0435\u0440 (Pentium M Dothan \u0432 Socket 478)|\u0423\u0441\u0442\u0430\u043d\u043e\u0432\u043a\u0430 \u0445\u043e\u043b\u043e\u0434\u043d\u043e\u0433\u043e \u043c\u043e\u0431\u0438\u043b\u044c\u043d\u043e\u0433\u043e Dothan 2.26GHz \u0432 \u043f\u043b\u0430\u0442\u0443 P4P800 \u0441 \u0440\u0435\u043a\u043e\u0440\u0434\u043e\u043c SuperPI";
        a14[3] = "Slocket Slot 1 to Socket 370 (Tualatin 1.4GHz)|\u041f\u0435\u0440\u0435\u0445\u043e\u0434\u043d\u0438\u043a \u0441 \u0440\u0443\u0447\u043d\u044b\u043c \u0432\u044b\u0431\u043e\u0440\u043e\u043c \u0432\u043e\u043b\u044c\u0442\u0430\u0436\u0430 \u0434\u0436\u0430\u043c\u043f\u0435\u0440\u0430\u043c\u0438 \u0434\u043b\u044f \u0440\u0430\u0431\u043e\u0442\u044b Tualatin \u043d\u0430 i440BX";
        a14[4] = "\u041a\u0430\u0440\u0430\u043d\u0434\u0430\u0448\u043d\u044b\u0439 \u043c\u043e\u0434 L1 \u043d\u0430 Socket A (Athlon XP 2500+)|\u0417\u0430\u043c\u044b\u043a\u0430\u043d\u0438\u0435 \u0433\u0440\u0430\u0444\u0438\u0442\u043e\u043c \u0434\u043e\u0440\u043e\u0436\u0435\u043a L1 \u043c\u043e\u0441\u0442\u0438\u043a\u043e\u0432 \u0434\u043b\u044f \u0440\u0430\u0437\u0431\u043b\u043e\u043a\u0438\u0440\u043e\u0432\u043a\u0438 \u0441\u0432\u043e\u0431\u043e\u0434\u043d\u043e\u0433\u043e \u043c\u043d\u043e\u0436\u0438\u0442\u0435\u043b\u044f CPU";
        a14[5] = "BSEL Tape Mod (FSB 800 -> 1066 / 1333 MHz)|\u0418\u0437\u043e\u043b\u044f\u0446\u0438\u044f \u043a\u043e\u043d\u0442\u0430\u043a\u0442\u0430 BSEL \u0441\u043a\u043e\u0442\u0447\u0435\u043c \u0434\u043b\u044f \u0431\u0435\u0441\u043f\u043b\u0430\u0442\u043d\u043e\u0433\u043e \u0440\u0430\u0437\u0433\u043e\u043d\u0430 \u043d\u0430 \u0434\u0435\u0448\u0435\u0432\u044b\u0445 OEM \u043f\u043b\u0430\u0442\u0430\u0445 \u0431\u0435\u0437 BIOS OC";
        a14[6] = "BGA Interposer \u041c\u0443\u0442\u0430\u043d\u0442 (Core i7-4980HQ \u043d\u0430 H81)|\u041c\u043e\u0431\u0438\u043b\u044c\u043d\u044b\u0439 \u0447\u0438\u043f BGA1366/LGA1150 \u0441 \u043c\u043e\u0449\u043d\u0435\u0439\u0448\u0435\u0439 \u0433\u0440\u0430\u0444\u0438\u043a\u043e\u0439 Iris Pro 5200 \u043d\u0430 \u0431\u044e\u0434\u0436\u0435\u0442\u043d\u043e\u0439 \u043f\u043b\u0430\u0442\u0435";
        a14[7] = "Lin-Lin Tualatin \u0410\u0434\u0430\u043f\u0442\u0435\u0440 (VRM 8.5 \u043f\u043e\u043d\u0438\u0436\u0435\u043d\u0438\u0435)|\u041f\u043b\u0430\u0442\u0430-\u043f\u0435\u0440\u0435\u0445\u043e\u0434\u043d\u0438\u043a \u0441 \u043f\u0440\u0435\u043e\u0431\u0440\u0430\u0437\u043e\u0432\u0430\u0442\u0435\u043b\u0435\u043c \u043f\u0438\u0442\u0430\u043d\u0438\u044f 1.45V \u0434\u043b\u044f \u0437\u0430\u043f\u0443\u0441\u043a\u0430 PIII-S \u043d\u0430 \u043f\u043b\u0430\u0442\u0430\u0445 1998 \u0433\u043e\u0434\u0430";
        a14[8] = "QQLS / QTJ2 8C/16T \u041c\u043e\u0431\u0438\u043b\u044c\u043d\u044b\u0439 \u041c\u0443\u0442\u0430\u043d\u0442 \u043d\u0430 H110|\u0423\u0441\u0442\u0430\u043d\u043e\u0432\u043a\u0430 \u043a\u0438\u0442\u0430\u0439\u0441\u043a\u043e\u0433\u043e 8-\u044f\u0434\u0435\u0440\u043d\u043e\u0433\u043e \u043c\u0443\u0442\u0430\u043d\u0442\u0430 \u0441\u043e \u0441\u043d\u044f\u0442\u043e\u0439 \u043a\u0440\u044b\u0448\u043a\u043e\u0439 \u043d\u0430 \u0441\u0430\u043c\u0443\u044e \u0434\u0435\u0448\u0451\u0432\u0443\u044e \u043f\u043b\u0430\u0442\u0443 H110";
        a14[9] = "\u0412\u043d\u0435\u0448\u043d\u044f\u044f \u0432\u0438\u0434\u0435\u043e\u043a\u0430\u0440\u0442\u0430 eGPU RTX 4090 \u0447\u0435\u0440\u0435\u0437 ExpressCard|\u041f\u0440\u043e\u0431\u0440\u043e\u0441 \u0448\u0438\u043d\u044b PCIe x1 \u0447\u0435\u0440\u0435\u0437 \u0430\u0434\u0430\u043f\u0442\u0435\u0440 Beast GDC \u0438 \u0432\u043d\u0435\u0448\u043d\u0438\u0439 \u0431\u043b\u043e\u043a \u043f\u0438\u0442\u0430\u043d\u0438\u044f 850W";
        a14[10] = "\u0420\u0430\u0437\u0431\u043b\u043e\u043a\u0438\u0440\u043e\u0432\u043a\u0430 4-\u0433\u043e \u044f\u0434\u0440\u0430 Phenom II X3 -> X4 (ACC)|\u0410\u043a\u0442\u0438\u0432\u0430\u0446\u0438\u044f \u0437\u0430\u0431\u043b\u043e\u043a\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0445 \u044f\u0434\u0435\u0440 \u0438 6MB \u043a\u044d\u0448\u0430 L3 \u0447\u0435\u0440\u0435\u0437 \u0444\u0443\u043d\u043a\u0446\u0438\u044e Advanced Clock Calibration";
        a14[11] = "\u041f\u0435\u0440\u0435\u043f\u0430\u0439\u043a\u0430 BGA-\u0447\u0438\u043f\u043e\u0432 RAM \u0434\u043e 16GB \u043d\u0430 \u041d\u0435\u0442\u0431\u0443\u043a\u0435|\u0412\u044b\u043f\u0430\u0439\u043a\u0430 \u0437\u0430\u0432\u043e\u0434\u0441\u043a\u0438\u0445 \u0447\u0438\u043f\u043e\u0432 \u043f\u0430\u043c\u044f\u0442\u0438 512MB \u0438 \u043c\u043e\u043d\u0442\u0430\u0436 \u0447\u0438\u043f\u043e\u0432 \u0443\u0434\u0432\u043e\u0435\u043d\u043d\u043e\u0439 \u043f\u043b\u043e\u0442\u043d\u043e\u0441\u0442\u0438 \u0441 \u043f\u0440\u0430\u0432\u043a\u043e\u0439 SPD";
        a14[12] = "\u041c\u043e\u0434\u0434\u0438\u043d\u0433 BIOS \u043f\u043e\u0434 NVMe SSD \u043d\u0430 \u043f\u043b\u0430\u0442\u0430\u0445 \u0431\u0435\u0437 UEFI|\u0412\u043d\u0435\u0434\u0440\u0435\u043d\u0438\u0435 NvmExpressDxe \u0434\u0440\u0430\u0439\u0432\u0435\u0440\u0430 \u0432 \u043e\u0431\u0440\u0430\u0437 AMI/Award BIOS \u0438 \u043f\u0440\u043e\u0448\u0438\u0432\u043a\u0430 \u043f\u0440\u043e\u0433\u0440\u0430\u043c\u043c\u0430\u0442\u043e\u0440\u043e\u043c CH341A";
        a14[13] = "Skylake Non-K BCLK \u0420\u0430\u0437\u0433\u043e\u043d (Core i5-6400 @ 4.6GHz)|\u041e\u0442\u043a\u0430\u0442 \u043d\u0430 \u0438\u043d\u0436\u0435\u043d\u0435\u0440\u043d\u044b\u0439 Non-K OC BIOS \u043f\u043b\u0430\u0442\u044b Z170 \u0434\u043b\u044f \u0444\u043e\u0440\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u044f \u0448\u0438\u043d\u044b BCLK \u0434\u043e 170MHz";
